// === Tab: mySketch ===
// need to find a better song option, something more upbeat and appropriate for the theme

let sound, amplitude;
let particles=[]; // array of particle objects
let dImg;
let gravity;
let wind;

function preload(){
  sound = loadSound('https://openprocessing.org/sketch/1835918/files/Heart Beat.mp3');
	dImg = loadImage("https://openprocessing.org/sketch/1835918/files/Heart.png"); 
	tImg = loadImage("https://openprocessing.org/sketch/1835918/files/Heart2.png"); 
	fontAdvent = loadFont('https://openprocessing.org/sketch/1835918/files/Adventuro.ttf');
}

function setup() {
  let cnv = createCanvas(windowWidth, windowHeight); 
	sound.loop(); 
  amplitude = new p5.Amplitude();
	noStroke(); 
	gravity = createVector(0,0.01);
	wind = createVector(0,0.004);

}

function draw() { 
  background('#40130F');
		let level = amplitude.getLevel(); //using amp to control size of the hearts 
		let size = map(level, 2, 1, 2, 15); //size of hearts


  if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
  	particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), dImg)) //add new particle to array      //ellipse(width/2, height/2, size, size);
		particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), tImg))
		}

	for(let i=0; i<particles.length; i++) {
		particles[i].addForce(gravity); 
		particles[i].addForce(wind);
		particles[i].update(); 
}
	// font, size, position and fill of text
	textFont(fontAdvent);
	textAlign(CENTER);
	textSize(size*2); //using amp x2 to control size of hearts 
	fill(255);
  text('Happy Valentines Day', width/2, height/2); 
}
class Particle {

	constructor(x, y, c, b) {
		this.loc = createVector(x, y); // location vec
		this.vel = createVector(random(0,1), random(-0.5,0.5));
	  this.img = c; 
	} // end constructor

	addForce(force) {
		this.vel.add(force) ;
	}

	update() {
		this.loc.add(this.vel);
		push();
		translate(this.loc.x, this.loc.y);
		var level = amplitude.getLevel(); //using amp to control size of the hearts 
		var size = map(level, 2, 1, 2, 15); //size of hearts
		image(this.img, 0, 0, size, size); 
		pop();

		if(this.loc.y > height || this.loc.y <= 0){
			this.vel.y = -(this.vel.y); // bounce on floor
		}
		if(this.loc.x > width || this.loc.x <= 0){
			this.vel.x = -(this.vel.x); // bounce on right wall
		}

	} // end update

} // end class Particle


function togglePlay() {
  if (sound.isPlaying() ){
    sound.pause();
  } else {
    sound.loop();
		amplitude = new p5.Amplitude();
		amplitude.setInput(sound);
  }
}

